export function deprecationMiddleware(req: Request, res: Response, next: NextFunction) {
  // Signal API deprecation using standard IETF RFC headers
  res.setHeader("Deprecation", "@1727913600"); // Unix timestamp
  res.setHeader("Sunset", "Wed, 31 Dec 2026 23:59:59 GMT");
  res.setHeader(
    "Link",
    '<https://api.example.com/docs/v1-migration>; rel="sunset"; type="text/html"'
  );
  next();
}
